import useSWR from "swr";
import { fetcher } from "../utils/fetcher";

export function useUser({ id }) {
    let user = null

    if(id) {
        user = useSWR(`https://jsonplaceholder.typicode.com/users/${id}`, fetcher)   
    }else {
        user = useSWR("https://jsonplaceholder.typicode.com/users", fetcher)
    }

    return {
        data: user.data,
        isLoading: user.isLoading,
        isError: user.error
    }
}
